import React from 'react';
import { useParams } from 'react-router-dom'; // Import useParams for getting the ID
import './StudentDetails.css';

const StudentDetails = () => {
  const { id } = useParams(); // Get the student ID from the URL

  // Dummy data, this could be replaced by an API call or fetched from context/state
  const students = [
    { id: 1, name: 'Abinay', department: 'CSE', skills: 'Java, Python', rating: 4.5, cgpa: 8.7 },
    { id: 2, name: 'Jane Smith', department: 'ECE', skills: 'C, Verilog', rating: 4.2, cgpa: 8.4 },
    { id: 3, name: 'Alice Brown', department: 'ME', skills: 'SolidWorks, MATLAB', rating: 4.1, cgpa: 8.6 },
  ];

  // Find the student by ID
  const student = students.find(student => student.id === parseInt(id));

  return (
    <div className="student-details-container">
      {student ? (
        <>
          <h1>{student.name}'s Profile</h1>
          <p><strong>Department:</strong> {student.department}</p>
          <p><strong>Skills:</strong> {student.skills}</p>
          <p><strong>Rating:</strong> {student.rating}</p>
          <p><strong>CGPA:</strong> {student.cgpa}</p>
        </>
      ) : (
        <p>Student not found</p>
      )}
    </div>
  );
};

export default StudentDetails;
